#include "gpu_batch_state.cuh"
#include <cstdio>
int main(){using namespace tao::dual;try{int n=129,N=4*n;Device old(Vec(N,.4f)),u(Vec(N,.2f)),g(Vec(N,-.3f)),y(N),dy(Vec(N,1)),dold(Vec(N,0)),du(Vec(N,0)),dg(Vec(N,0));unsigned active[4]={1,0,1,0},reset[4]={0,0,1,1};unsigned *a,*r;check(cudaMalloc(&a,16));check(cudaMalloc(&r,16));check(cudaMemcpy(a,active,16,cudaMemcpyHostToDevice));check(cudaMemcpy(r,reset,16,cudaMemcpyHostToDevice));batch_state_update<<<(N+127)/128,128>>>(old.p,u.p,g.p,y.p,a,r,n,4);batch_state_backward<<<(N+127)/128,128>>>(old.p,u.p,g.p,dy.p,dold.p,du.p,dg.p,a,r,n,4);check(cudaGetLastError());auto yy=y.host(),dd=dold.host(),uu=du.host(),gg=dg.host();for(int i=0;i<N;++i){int s=i/n;if(!active[s]){if(yy[i]!=.4f||dd[i]!=1||uu[i]!=0||gg[i]!=0)return 1;}else{float gate=1/(1+std::exp(.3f)),v=reset[s]?0:.4f,c=std::tanh(.2f);if(std::abs(yy[i]-(v+gate*(c-v)))>1e-6||std::abs(dd[i]-(reset[s]?0:1-gate))>1e-6||std::abs(uu[i]-gate*(1-c*c))>1e-6||std::abs(gg[i]-(c-v)*gate*(1-gate))>1e-6)return 2;}}cudaFree(a);cudaFree(r);printf("PASS active reset padding forward/backward 4slots including inactive reset\n");return 0;}catch(const std::exception&e){printf("FAIL %s\n",e.what());return 3;}}
